function buildingLimitMessage(c=calc()){
 const b=c.buildingCapacity;
 return b.source?`Referência informada: até ${b.maxFloors} ${b.maxFloors===1?'pavimento':'pavimentos'}. ${b.aboveReference?'O cenário ultrapassa essa referência.':'O cenário não ultrapassa essa referência.'} Aplicabilidade não validada.`:'Limite de pavimentos a confirmar. Informe o gabarito de uma consulta ou certidão do terreno.';
}
function buildingCapacityHeader(){
 const c=calc(),b=c.buildingCapacity;
 return `<div class="floor-model-header"><div class="floor-current"><span class="floor-kicker">NO MODELO 3D</span><div class="floor-count"><strong>${b.simulatedFloors}</strong><span>${b.simulatedFloors===1?'pavimento':'pavimentos'}<small>${esc(BuildingCapacity.describe(b.simulatedFloors))}</small></span></div><p>${number(c.height)} m de altura simulada · 3 m por pavimento</p></div><section class="floor-limit ${b.aboveReference?'over-limit':''}" aria-label="Limite de pavimentos do terreno"><span class="floor-kicker">LIMITE PARA ESTE TERRENO</span><strong>${b.source?b.maxFloors===0?'Sem pavimentos na referência':`Até ${b.maxFloors} ${b.maxFloors===1?'pavimento':'pavimentos'}*`:'A confirmar'}</strong><p>${b.source?'*Conforme documento informado; aplicação não validada.':'Depende do gabarito e das restrições aplicáveis ao lote.'}</p>${b.aboveReference?`<p class="floor-limit-warning">${icon('alert')}Cenário acima da referência em ${b.simulatedFloors-b.maxFloors} ${b.simulatedFloors-b.maxFloors===1?'pavimento':'pavimentos'}. Os níveis excedentes aparecem em laranja.</p>`:''}<div class="floor-limit-actions">${btn(b.source?'Conferir documento':'Informar limite documental','book','building-limit')}${b.source&&b.maxFloors>0&&b.maxFloors!==state.floors?btn('Simular '+b.maxFloors+' pav.','layers','apply-building-limit'):''}</div></section>${b.modeledFloors!==b.simulatedFloors?`<p class="floor-geometry-warning">${icon('alert')}${b.modeledFloors} de ${b.simulatedFloors} pavimentos possuem área de implantação no cenário. Os demais ficaram sem área após os recuos.</p>`:''}</div>`;
}
function openBuildingLimit(){
 const input=state.lot.buildingLimit||{};
 modal('Limite de pavimentos do terreno',`<p>Informe o número máximo de pavimentos indicado para este terreno em uma certidão ou consulta urbanística. A zona e os recuos, isoladamente, não confirmam esse número.</p><form id="building-limit-form"><label class="setback-field" for="building-max-floors">Máximo de pavimentos no documento<input id="building-max-floors" name="maxFloors" type="number" min="0" max="80" step="1" value="${esc(input.maxFloors??'')}" required aria-describedby="building-count-help" placeholder="Ex.: 8"></label><p class="setback-help" id="building-count-help">Inclua o térreo: 8 pavimentos = térreo + 7 andares. Informe 0 se o documento não permitir edificação. Subsolos e coberturas especiais exigem análise própria. Uma altura em metros não determina, sozinha, a quantidade permitida.</p><label class="setback-field" for="building-reference">Documento e trecho que definem o limite<input id="building-reference" name="reference" maxlength="250" value="${esc(input.reference||'')}" required placeholder="Órgão, número, data e item da certidão"></label><label class="setback-field" for="building-reference-url">Link da fonte (opcional)<input id="building-reference-url" name="url" type="url" value="${esc(input.url||'')}" placeholder="https://..."></label><p class="setback-current-status">O protótipo compara o cenário com a referência informada. A vigência e a aplicação ao terreno precisam ser verificadas.</p><p class="floor-form-error" role="alert" hidden></p><div class="floor-form-actions"><button class="btn primary" type="submit">${icon('check')}Aplicar referência ao 3D</button>${input.maxFloors!==undefined?`<button class="btn" type="button" data-action="clear-building-limit">Remover referência</button>`:''}</div></form>`,'',true);
 $('.modal').classList.add('setback-modal');$('.modal-backdrop').classList.add('setback-backdrop');
}
function buildingCapacityReport(){
 const c=calc(),b=c.buildingCapacity;
 return `<div class="report-block"><h3>Pavimentos e gabarito informado</h3><p>${BuildingCapacity.count(b.simulatedFloors)} no cenário: ${esc(BuildingCapacity.describe(b.simulatedFloors))}. Pavimentos com área de implantação: ${b.modeledFloors}. Altura simulada: ${number(c.height)} m, com premissa de 3 m por pavimento.</p><p>${esc(buildingLimitMessage(c))}</p>${b.source?`<p>Documento: ${esc(b.source.reference)}${b.source.url?` · <a href="${esc(b.source.url)}" target="_blank" rel="noopener noreferrer">Abrir fonte</a>`:''}</p>`:''}<p>Contagem acima do solo, incluindo térreo. O gabarito informado não confirma uso, CA, ocupação, aprovação ou restrições especiais do lote.</p></div>`;
}
document.addEventListener('submit',event=>{
 if(event.target.id!=='building-limit-form')return;
 event.preventDefault();const data=new FormData(event.target),input=Object.fromEntries(data),source=BuildingCapacity.document(input);
 if(!source||(input.url&&!source.url)){const error=event.target.querySelector('[role=alert]');error.hidden=false;error.textContent='Informe um número inteiro entre 0 e 80, a referência do documento e um link http ou https válido, se preenchido.';return}
 state.lot.buildingLimit=source;closeModal();render();focusMain();notify('Referência de pavimentos aplicada ao 3D. Salve o estudo para guardá-la na sua conta.');
});
